package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseO3MigrationTest extends MigrationTestSupport {
 @Test void failedUpgradeRollsBackThenPreservesLegacyProgressWithoutInventingCompletions(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_o3_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("64").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{UUID user=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES ('o3-upgrade@example.test','synthetic','ACTIVE') RETURNING id",UUID.class),path=db.queryForObject("SELECT id FROM guided_growth_paths ORDER BY id LIMIT 1",UUID.class);db.update("INSERT INTO user_growth_path_progress(user_id,path_id,progress,completed) VALUES (?,?,60,FALSE)",user,path);var paths=db.queryForList("SELECT to_jsonb(t)::text AS record FROM guided_growth_paths t ORDER BY id");var old=db.queryForMap("SELECT progress,completed,started_at FROM user_growth_path_progress WHERE user_id=?",user);db.execute("CREATE TABLE learning_lesson_views(synthetic_conflict TEXT)");var f=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("65").load();assertThatThrownBy(f::migrate).isInstanceOf(org.flywaydb.core.api.FlywayException.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.columns WHERE table_schema=? AND table_name='guided_growth_paths' AND column_name='resource_id'",Integer.class,schema)).isZero();db.execute("DROP TABLE learning_lesson_views");f.migrate();f.validate();f.migrate();assertThat(db.queryForList("SELECT (to_jsonb(t)-'resource_id')::text AS record FROM guided_growth_paths t ORDER BY id")).isEqualTo(paths);assertThat(db.queryForMap("SELECT progress,completed,started_at FROM user_growth_path_progress WHERE user_id=?",user)).isEqualTo(old);assertThat(db.queryForObject("SELECT legacy_progress FROM user_growth_path_progress WHERE user_id=?",Integer.class,user)).isEqualTo(60);assertThat(db.queryForObject("SELECT count(*) FROM learning_lesson_completions",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM learning_course_completions",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM guided_growth_paths WHERE resource_id IS NOT NULL",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
